const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const northernHemisphere = ee.Geometry.Rectangle([-180, 0, 180, 90], null, false);
  const bandName = 'tropospheric_NO2_column_number_density';
  // Use a larger scale for a global region to avoid memory issues and timeouts.
  const scale = 50000;

  // Function to get and process data for a given year
  const getNO2Mean = (year, geometry) => {
    const startDate = ee.Date.fromYMD(year, 1, 1);
    const endDate = ee.Date.fromYMD(year, 12, 31);

    let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterDate(startDate, endDate)
      .filterBounds(geometry)
      .select(bandName)
      .filter(ee.Filter.gt('qa_value', 0.75)); // Filter for good quality data

    // Check if the collection is empty
    return collection.size().eq(0).evaluate().then(isEmpty => {
      if (isEmpty) {
        return { year: year, value: null, numImages: 0, numPixels: 0 };
      }

      const annualMean = collection.mean();

      // Calculate the mean value and valid pixel count
      return annualMean.reduceRegion({
        reducer: ee.Reducer.mean().combine({
          reducer2: ee.Reducer.count(),
          sharedInputs: true
        }),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e10
      }).evaluate().then(result => {
        const meanValue = result ? result[bandName + '_mean'] : null;
        const pixelCount = result ? result[bandName + '_count'] : 0;
        return { year: year, value: meanValue, numImages: collection.size().getInfo(), numPixels: pixelCount };
      });
    });
  };

  try {
    // 2. Data Acquisition & Check
    const result2019 = await getNO2Mean(2019, northernHemisphere);
    const result2020 = await getNO2Mean(2020, northernHemisphere);

    if (result2019.numImages === 0 || result2020.numImages === 0) {
      console.log(`2019 Images: ${result2019.numImages}, 2020 Images: ${result2020.numImages}`);
      console.log('C1');
      return;
    }

    if (result2019.numPixels === 0 || result2020.numPixels === 0) {
      console.log(`2019 Images: ${result2019.numImages} (Val: ${result2019.numPixels}), 2020 Images: ${result2020.numImages} (Val: ${result2020.numPixels})`);
      console.log('C2');
      return;
    }

    // 4. Calculation & Validation
    const no2_2019 = result2019.value;
    const no2_2020 = result2020.value;

    if (no2_2019 === null || isNaN(no2_2019) || no2_2020 === null || isNaN(no2_2020)) {
      console.log(`2019 Mean: ${no2_2019}, 2020 Mean: ${no2_2020}`);
      console.log('C3');
      return;
    }

    console.log(`2019 Images: ${result2019.numImages} (Val: ${result2019.numPixels})`);
    console.log(`2019 NO2 (x10^-6 mol/m^2): ${no2_2019 * 1e6:.4f}`);
    console.log(`2020 Images: ${result2020.numImages} (Val: ${result2020.numPixels})`);
    console.log(`2020 NO2 (x10^-6 mol/m^2): ${no2_2020 * 1e6:.4f}`);

    if (no2_2020 > no2_2019) {
      console.log('A'); // Yes, NO2 concentrations increased
    } else {
      console.log('B'); // No, NO2 concentrations did not increase
    }

  } catch (error) {
    console.error("An error occurred during analysis:", error);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
